// Furnishing — the detail layer.
//
// Markings are generated by the geometry pass from the cross-section (they are a property of the
// road's shape). Everything here is *placed*: crossings, humps, bollards, sign faces, signal heads,
// lighting columns, gullies, passing places, rail crossings, subway entrances and guardrail runs.
// Each placement is a distance along the road plus a side, so a road can be re-shaped or re-profiled
// and its furniture stays where the designer put it.
//
// Placement is deterministic per (seed, road id) so a map looks the same every time it is opened.

import { mulberry32 } from './generate.js';
import { sampleRoad, roadProfile } from './network.js';
import { profileOffsets, profileExtents } from './profiles.js';

const RANK = { motorway: 7, expressway: 6, ramp: 6, arterial: 5, busway: 5, collector: 4, tramway: 4, local: 3, lane: 2, service: 1, cycleway: 0, footway: 0, pedestrian: 0, 'parking-aisle': 0 };

function sideline(profile, type) {
  const offs = profileOffsets(profile).filter((o) => o.strip.type === type);
  return offs;
}

/** The kerb line offset on a given side: where furniture stands and where a crossing lands. */
export function kerbOffset(profile) {
  const offs = profileOffsets(profile);
  const kerbs = offs.filter((o) => o.strip.type === 'kerb');
  const right = kerbs.filter((o) => o.from >= 0);
  const left = kerbs.filter((o) => o.to <= 0);
  const ext = profileExtents(profile);
  return {
    right: right.length ? right[0].to : ext.right,
    left: left.length ? left[left.length - 1].from : -ext.left,
  };
}

export function furnishRoad(project, road, charter, terrain) {
  const rng = mulberry32(hashString(road.id) ^ project.options.seed);
  const frames = sampleRoad(road, 6);
  if (frames.length < 2) return;
  const len = frames[frames.length - 1].s;
  const profile = roadProfile(project, road);
  const rank = RANK[road.class] ?? 3;
  const kerb = kerbOffset(profile);
  const supply = charter.supply;
  const d = road.details = {
    crossings: [], humps: [], bollards: [], busStops: [], signs: [], lights: [],
    gullies: [], manholes: [], passing: [], rail: [], subway: [], guardrail: [], wear: [], chicanes: [], islands: [],
  };
  if (len < 12) return;

  // ── Guardrail runs: along bridge and tunnel approaches, and motorway shoulder edge ─────────────
  for (const span of road.spans || []) {
    if (span.kind === 'bridge' || span.kind === 'tunnel') {
      const s0 = frames[Math.min(span.i0, frames.length - 1)].s;
      const s1 = frames[Math.min(span.i1, frames.length - 1)].s;
      d.guardrail.push({ s0, s1, side: 'both', kind: span.kind === 'tunnel' ? 'concrete step barrier' : 'steel railing' });
    }
  }
  if (rank >= 6) d.guardrail.push({ s0: 0, s1: Math.min(len, 200), side: 'both', kind: 'W-beam' });

  // ── Lighting: spacing is a function of mounting height, not a habit ────────────────────────────
  if (rank >= 4) {
    const spacing = rank >= 6 ? 48 : 34;
    for (let s = spacing * 0.5; s < len - 10; s += spacing) {
      const onMedian = rank >= 6 && profile.centre && profile.centre.type === 'median';
      d.lights.push({ s, side: onMedian ? 'centre' : (rng() < 0.5 ? 'left' : 'right'), kind: rank >= 6 ? '12 m dual arm' : '8 m side-entry' });
    }
  }

  // ── Drainage: gullies at the low side, manholes on a long cycle ─────────────────────────────────
  for (let s = 20; s < len; s += 38 + rng() * 22) d.gullies.push({ s, side: rng() < 0.5 ? 'left' : 'right' });
  for (let s = 45; s < len; s += 90 + rng() * 60) d.manholes.push({ s, side: rng() < 0.5 ? 'left' : 'right', kind: 'chamber cover' });

  // ── Wear and reinstatement: what makes a road look used rather than drawn ──────────────────────
  const wearCount = Math.max(1, Math.round(len / 70));
  for (let k = 0; k < wearCount; k += 1) {
    d.wear.push({ s: rng() * len, len: 8 + rng() * 26, side: rng() < 0.5 ? 'left' : 'right', kind: rng() < 0.55 ? 'wheel-track wear' : rng() < 0.8 ? 'utility patch' : 'reinstatement', width: 1 + rng() * 2.4 });
  }

  // ── Chicanes and modal filters on quiet streets ────────────────────────────────────────────────
  if (rank === 3 && supply.humps > 0.3 && rng() < 0.22 && len > 120) {
    d.chicanes.push({ s: len * (0.3 + rng() * 0.4), side: rng() < 0.5 ? 'left' : 'right', len: 9 });
  }

  // ── Speed humps ────────────────────────────────────────────────────────────────────────────────
  if (rank === 3 && supply.humps > 0 && rng() < Math.min(1, supply.humps * 1.6)) {
    const spacing = 90 + rng() * 50;
    for (let s = 40; s < len - 30; s += spacing) {
      d.humps.push({ s, kind: supply.humps > 0.6 ? 'trapezoidal hump' : 'round-top bump', height: supply.humps > 0.6 ? 0.1 : 0.075, width: 3.7 });
    }
  }

  // ── Bus stops on any road that carries a bus strip ─────────────────────────────────────────────
  const busStrips = sideline(profile, 'bus').concat(sideline(profile, 'bus-stop'));
  if (busStrips.length && supply.busNetwork && len > 90) {
    const count = Math.max(1, Math.round(len / 380));
    for (let k = 0; k < count; k += 1) {
      const s = (len * (k + 0.6)) / (count + 0.4);
      const strip = busStrips[k % busStrips.length];
      d.busStops.push({
        s, side: strip.from >= 0 ? 'right' : 'left',
        kind: rng() < 0.7 ? 'shelter + RTI' : 'pole only',
        shelter: rng() < 0.7, cage: true,
      });
    }
  }

    // ── Crossing marks: the paint goes down, the beacon or signal hardware follows ────────────────
  const crossingsWanted = rank >= 4 ? Math.floor(len / 260) : Math.floor(len / 420);
  for (let k = 0; k < crossingsWanted; k += 1) {
    const s = (len * (k + 0.5)) / Math.max(1, crossingsWanted);
    const signalised = rank >= 5 || (rank === 4 && rng() < 0.4);
    d.crossings.push({
      s,
      kind: signalised ? 'signal' : (charter.id === 'us-grid' ? 'continental' : 'zebra'),
      width: signalised ? 3.6 : 3.0,
      signals: signalised ? 2 : 0,
      beacons: signalised ? 0 : 2,
      raised: supply.humps > 0.5,
    });
    if (!signalised || rng() < 0.5) {
      d.signs.push({ s: Math.max(6, s - 18), side: 'left', kind: 'crossing warning' });
    }
  }

  // ── Bollards: runs, not decorations. Cycle tracks at junctions, and modal filters ──────────────
  const cycleTracks = sideline(profile, 'cycle-track').concat(sideline(profile, 'cycle'));
  if (cycleTracks.length && supply.cycleNetwork && len > 60) {
    for (let s = 18; s < len - 18; s += 120 + rng() * 90) {
      const strip = cycleTracks[0];
      d.bollards.push({ s, side: strip.from >= 0 ? 'right' : 'left', offset: strip.from >= 0 ? strip.from + 0.25 : strip.to - 0.25, count: 1, kind: 'flexible post' });
    }
  }
  if ((road.class === 'pedestrian' || road.class === 'cycleway') && len > 20) {
    // A modal filter across the whole width at each end and every so often between.
    for (const s of [6, len - 6, ...(len > 180 ? [len * 0.5] : [])]) {
      d.bollards.push({ s, side: 'both', offset: null, count: Math.max(3, Math.round(profileExtents(profile).width / 1.5)), kind: road.class === 'pedestrian' ? 'steel core' : 'timber', across: true });
    }
  }

  // ── Passing places on single-track lanes ──────────────────────────────────────────────────────
  if (road.class === 'lane' && len > 120) {
    let flip = rng() < 0.5;
    for (let s = 70; s < len - 40; s += 150 + rng() * 90) {
      d.passing.push({ s, side: flip ? 'left' : 'right', len: 20, width: 2.5 });
      flip = !flip;
    }
  }

  // ── Signs at junctions: give way, roundabout, no entry ────────────────────────────────────────
  if (rank >= 2 && rank <= 4) d.signs.push({ s: len - 8, side: 'left', kind: 'give way' });

  // ── Accessible and loading bays where there is a parking strip ────────────────────────────────
  const park = sideline(profile, 'parking');
  if (park.length && len > 60 && rng() < 0.5) {
    d.signs.push({ s: len * (0.2 + rng() * 0.5), side: park[0].from >= 0 ? 'right' : 'left', kind: 'parking bay' });
  }

  // ── Pedestrian subways under the widest roads, where the charter asks for them ────────────────
  if (rank >= 5 && charter.id === 'nfs-arterial' && len > 300 && rng() < 0.28) {
    d.subway.push({
      s: len * (0.3 + rng() * 0.4), side: rng() < 0.5 ? 'left' : 'right',
      kind: 'cut-and-cover', width: 3.6, depth: 3.2, steps: true, lighting: true,
    });
  }

  road.details = d;
}

/* ── Rail crossings ─────────────────────────────────────────────────────────────────────────────── */

const PROTECTION_BY_RANK = [
  { maxRank: 2, kind: 'open (passive)' },
  { maxRank: 3, kind: 'user-worked gates' },
  { maxRank: 4, kind: 'automatic half-barrier' },
  { maxRank: 6, kind: 'automatic full barrier' },
  { maxRank: 9, kind: 'manned gates' },
];

/** Crossing protection follows the road class: a lane gets gates, a motorway gets a bridge instead. */
export function furnishRailCrossings(project) {
  const crossings = [];
  for (const line of project.rail) {
    for (let i = 1; i < line.points.length; i += 1) {
      const a = line.points[i - 1];
      const b = line.points[i];
      for (const road of project.roads) {
        const pts = road.points;
        for (let k = 1; k < pts.length; k += 1) {
          const c = pts[k - 1];
          const d = pts[k];
          const den = (b[0] - a[0]) * (d[2] - c[2]) - (b[2] - a[2]) * (d[0] - c[0]);
          if (Math.abs(den) < 1e-9) continue;
          const t = ((c[0] - a[0]) * (d[2] - c[2]) - (c[2] - a[2]) * (d[0] - c[0])) / den;
          const u = ((c[0] - a[0]) * (b[2] - a[2]) - (c[2] - a[2]) * (b[0] - a[0])) / den;
          if (t < 0 || t > 1 || u < 0 || u > 1) continue;
          const x = a[0] + (b[0] - a[0]) * t;
          const z = a[2] + (b[2] - a[2]) * t;
          const y = c[1] + (d[1] - c[1]) * u;
          const angle = Math.abs(Math.atan2(den, (b[0] - a[0]) * (d[0] - c[0]) + (b[2] - a[2]) * (d[2] - c[2])));
          const skew = 90 - (angle * 180) / Math.PI;
          const rank = RANK[road.class] ?? 3;
          const separated = rank >= 6;
          crossings.push({
            x, z, y, roadId: road.id, railId: line.id, skew,
            separated,
            kind: separated ? 'grade-separated' : (road.class === 'tramway' ? 'tram crossing' : PROTECTION_BY_RANK.find((p) => rank <= p.maxRank)?.kind || 'automatic full barrier'),
            barrier: !separated && rank >= 4,
            lights: !separated && rank >= 3,
            flangeway: 0.038,
          });
          break;
        }
      }
    }
  }
  return crossings;
}

export function furnishProject(project, charter, terrain) {
  const rng = mulberry32((project.options.seed ^ 0x5f3a) >>> 0);
  for (const road of project.roads) furnishRoad(project, road, charter, terrain);
  project.railCrossings = furnishRailCrossings(project);
  return project;
}

function hashString(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i += 1) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
